-- Prediction Module Migration (Part 2)
-- V7: Create Predictions table
-- Purpose: Store predictions generated by ML models with approval workflow

CREATE TABLE IF NOT EXISTS predictions (
    id BIGSERIAL PRIMARY KEY,
    machine_id BIGINT NOT NULL,
    model_id BIGINT NOT NULL,
    prediction_value NUMERIC(10,4) NOT NULL,
    confidence_score NUMERIC(3,2) NOT NULL CHECK (confidence_score >= 0 AND confidence_score <= 1.0),
    risk_level VARCHAR(20) NOT NULL CHECK (risk_level IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
    status VARCHAR(50) NOT NULL DEFAULT 'PENDING_REVIEW' CHECK (status IN ('PENDING_REVIEW', 'APPROVED', 'REJECTED', 'ACTED_UPON')),
    prediction_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    approved_date TIMESTAMP,
    action_date TIMESTAMP,
    approved_by VARCHAR(100),
    prediction_data TEXT, -- JSON with detailed prediction info
    notes TEXT,
    created_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_modified_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by VARCHAR(100),
    last_modified_by VARCHAR(100),
    version INTEGER DEFAULT 0,
    
    CONSTRAINT fk_predictions_machine FOREIGN KEY (machine_id) REFERENCES machines(id) ON DELETE CASCADE,
    CONSTRAINT fk_predictions_model FOREIGN KEY (model_id) REFERENCES ml_models(id) ON DELETE RESTRICT,
    CONSTRAINT chk_dates CHECK (approved_date IS NULL OR prediction_date <= approved_date),
    CONSTRAINT chk_action_date CHECK (action_date IS NULL OR approved_date <= action_date)
);

-- Indexes for common queries
CREATE INDEX idx_predictions_machine_id ON predictions(machine_id);
CREATE INDEX idx_predictions_model_id ON predictions(model_id);
CREATE INDEX idx_predictions_status ON predictions(status);
CREATE INDEX idx_predictions_risk_level ON predictions(risk_level);
CREATE INDEX idx_predictions_prediction_date ON predictions(prediction_date DESC);
CREATE INDEX idx_predictions_created_date ON predictions(created_date DESC);
CREATE INDEX idx_predictions_machine_date ON predictions(machine_id, prediction_date DESC);
CREATE INDEX idx_predictions_confidence ON predictions(confidence_score DESC);
CREATE INDEX idx_predictions_pending_review ON predictions(status) WHERE status = 'PENDING_REVIEW';
CREATE INDEX idx_predictions_approved ON predictions(approved_date DESC) WHERE status = 'APPROVED' AND action_date IS NULL;

-- ==================== COMMENT ====================
COMMENT ON TABLE predictions IS 'Stores ML model predictions for machines with approval workflow';
COMMENT ON COLUMN predictions.confidence_score IS 'Model confidence in prediction (0.0 to 1.0)';
COMMENT ON COLUMN predictions.risk_level IS 'Predicted risk: LOW, MEDIUM, HIGH, CRITICAL';
COMMENT ON COLUMN predictions.status IS 'Prediction workflow status: PENDING_REVIEW, APPROVED, REJECTED, ACTED_UPON';
COMMENT ON COLUMN predictions.prediction_data IS 'JSON containing model features and detailed prediction output';
